<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import SegmentTabs from '../../components/common/SegmentTabs.vue';import SearchFilterBar from '../../components/common/SearchFilterBar.vue';import EmptyState from '../../components/common/EmptyState.vue';import DetailDrawer from '../../components/common/DetailDrawer.vue';import StatusTag from '../../components/common/StatusTag.vue';import {workbenchRepository} from '../../services/workbenchRepository';import type {KnowledgeDocument} from '../../types';
const data=ref(workbenchRepository.load());const mode=ref('home');const keyword=ref('');const category=ref('全部');const onlyFavorites=ref(false);const selected=ref<KnowledgeDocument|null>(null);const uploadOpen=ref(false);const form=reactive({title:'',category:'',tags:'',summary:'',content:''});
const categories=computed(()=>['全部',...new Set(data.value.documents.map(item=>item.category))]);const rows=computed(()=>data.value.documents.filter(item=>(category.value==='全部'||item.category===category.value)&&(!onlyFavorites.value||item.favorite)&&[item.title,item.author,item.summary,...item.tags].join(' ').toLowerCase().includes(keyword.value.toLowerCase())));
const persist=()=>workbenchRepository.save(data.value);const toggle=(item:KnowledgeDocument)=>{item.favorite=!item.favorite;persist()};const add=()=>{if(!form.title||!form.category)return;data.value.documents.unshift({id:`DOC-${Date.now()}`,title:form.title,category:form.category,tags:form.tags.split(/[,，]/).map(x=>x.trim()).filter(Boolean),author:'当前用户',version:'V1.0',updatedAt:new Date().toISOString().slice(0,10),views:0,favorite:false,summary:form.summary,content:form.content});persist();uploadOpen.value=false;Object.assign(form,{title:'',category:'',tags:'',summary:'',content:''})};
</script>
<template><section class="workbench-view"><PageHeader eyebrow="KNOWLEDGE BASE" title="企业知识库" description="集中沉淀产品、研发、项目和企业规范。"><template #actions><button class="primary" @click="uploadOpen=true">上传文档</button></template></PageHeader><SegmentTabs v-model="mode" :items="[{key:'home',label:'知识首页'},{key:'center',label:'文档中心',count:data.documents.length}]"/><div v-if="mode==='home'"><div class="knowledge-hero"><div><span>让经验成为团队资产</span><h3>搜索企业知识、规范和项目沉淀</h3><input v-model="keyword" placeholder="搜索文档标题、作者或标签" @focus="mode='center'"/></div></div><h3 class="block-title">知识分类</h3><div class="category-grid"><button v-for="name in categories.filter(x=>x!=='全部')" :key="name" @click="category=name;mode='center'"><strong>{{name}}</strong><span>{{data.documents.filter(x=>x.category===name).length}} 篇文档</span></button></div><h3 class="block-title">最近更新</h3><div class="document-grid"><article v-for="item in data.documents.slice(0,3)" :key="item.id" @click="selected=item"><StatusTag :status="item.category"/><h3>{{item.title}}</h3><p>{{item.summary}}</p><small>{{item.author}} · {{item.updatedAt}}</small></article></div></div><template v-else><SearchFilterBar v-model="keyword" placeholder="搜索标题、作者、标签或摘要" :count="rows.length"><select v-model="category"><option v-for="item in categories" :key="item">{{item}}</option></select><label class="inline-check"><input v-model="onlyFavorites" type="checkbox"/>只看收藏</label></SearchFilterBar><div v-if="rows.length" class="document-grid"><article v-for="item in rows" :key="item.id" @click="selected=item"><div class="document-meta"><StatusTag :status="item.category"/><button class="favorite" @click.stop="toggle(item)">{{item.favorite?'★':'☆'}}</button></div><h3>{{item.title}}</h3><p>{{item.summary}}</p><div class="tag-list"><span v-for="tag in item.tags" :key="tag">{{tag}}</span></div><small>{{item.author}} · {{item.version}} · {{item.views}} 次浏览</small></article></div><EmptyState v-else title="没有匹配的文档" description="请调整搜索词或筛选条件。"/></template><DetailDrawer :open="Boolean(selected)" :title="selected?.title||'文档详情'" @close="selected=null"><template v-if="selected"><div class="document-detail"><div><StatusTag :status="selected.category"/><button class="favorite" @click="toggle(selected)">{{selected.favorite?'★ 已收藏':'☆ 收藏'}}</button></div><p class="muted">{{selected.author}} · {{selected.version}} · 更新于 {{selected.updatedAt}}</p><h4>摘要</h4><p>{{selected.summary||'暂无摘要'}}</p><h4>正文</h4><p class="document-content">{{selected.content||'暂无正文内容'}}</p><div class="tag-list"><span v-for="tag in selected.tags" :key="tag">{{tag}}</span></div></div></template></DetailDrawer><DetailDrawer :open="uploadOpen" title="上传 / 沉淀知识文档" @close="uploadOpen=false"><form class="work-item-form" @submit.prevent="add"><label>文档标题<input v-model="form.title" required placeholder="请输入文档标题"/></label><label>知识分类<select v-model="form.category" required><option value="" disabled>请选择知识分类</option><option>应知应会</option><option>产研规范</option><option>产品沉淀</option><option>项目沉淀</option></select></label><label>标签<input v-model="form.tags" placeholder="多个标签用逗号分隔"/></label><label>摘要<textarea v-model="form.summary" rows="3" placeholder="请输入文档摘要"/></label><label>正文<textarea v-model="form.content" rows="8" placeholder="请输入文档正文"/></label><div class="form-actions"><button type="button" class="secondary" @click="uploadOpen=false">取消</button><button class="primary">保存文档</button></div></form></DetailDrawer></section></template>
